#!/bin/sh
# Re-save the three (LA and Oakland are nonpartisan, so neutral bars; only D.C. carries parties) Nov 3, 2026 mayor charts with party colours. Run only AFTER the build with PerfBar.party is
# deployed (older servers silently drop `party`). Usage: sh scripts/boundaries/electionPartyBars-2026-11-13.sh
T=$(cat .scrape/admin.token); B=https://www.chronopin.com/api/pins
put(){ curl -s -m 90 -X PUT -H "Authorization: Bearer $T" -H "Content-Type: application/json" "$B/$1/performance" -d "$2" | head -c 120; echo; }
put 21048 '{"charts":[{"title":"Los Angeles mayor: share of the vote","unit":"% of votes","higherIsBetter":true,"note":"Nonpartisan race. 1,120,223 votes counted, 99% of expected vote in (NBC News, AP data).","sourceUrl":"https://www.nbcnews.com/politics/2026-elections/los-angeles-mayor-results","bars":[{"label":"Nithya Raman (winner)","value":54.9,"highlight":true},{"label":"Karen Bass (incumbent)","value":45.1}]}]}'
put 21049 '{"charts":[{"title":"D.C. mayor: share of the vote","unit":"% of votes","higherIsBetter":true,"note":"209,050 votes counted, 90% of expected vote in (NBC News, AP data). Votes: Lewis George 176,297; Hamilton 21,009; Gross 7,302.","sourceUrl":"https://www.nbcnews.com/politics/2026-elections/district-of-columbia-mayor-results","bars":[{"label":"Janeese Lewis George (D, winner)","value":84.3,"highlight":true,"party":"D"},{"label":"Rhonda Hamilton (I)","value":10.0,"party":"I"},{"label":"Robert Gross (I)","value":3.5,"party":"I"}]}]}'
put 21050 '{"charts":[{"title":"Oakland mayor: share of the vote","unit":"% of votes","higherIsBetter":true,"note":"Nonpartisan race; NBC lists no party for the candidates. 143,709 votes counted, 99% of expected vote in (NBC News, AP data).","sourceUrl":"https://www.nbcnews.com/politics/2026-elections/oakland-mayor-results","bars":[{"label":"Barbara Lee (incumbent, winner)","value":85.2,"highlight":true},{"label":"Julius Robinson","value":6.1},{"label":"Brenda Grisham","value":4.6}]}]}'
